Wrap the wait_for in try/except CancelledError to kill the child before re-raising:

    try:
        await asyncio.wait_for(
            proc.communicate(), timeout=self._task_timeout
        )
    except asyncio.TimeoutError:
        await _kill_and_reap(proc)
        self._repo.set_status(task_id, STATUS_TIMEOUT)
        return
    except asyncio.CancelledError:
        # Parent task cancelled (not timeout): kill the child so it
        # does not leak as an orphan (NFR-03). Re-raise so the
        # cancellation propagates upward per AC-8.5.
        try:
            proc.kill()
