def _redact_db_url_password(url: str) -> str:
    """[NFR-04] Redact password from a DB URL."""
    import re
    if not url:
        return url
    return re.sub(
        r"(://[^:]+:)[^@]+(@)",
        r"\1***\2",
        url,
    )
